   "funFact": "In early colonial days, a dispute between Chinese residents was settled here by an oath sworn while burning yellow paper and beheading a rooster, and it was treated as binding. 'Cat Street' comes from old slang: thieves were 'rats' and the buyers of stolen goods were 'cats'.",
